import{_ as n,C as o,o as s,c as r,j as t,a as i,E as d,a2 as l}from"./chunks/framework.sc8Z_ZE3.js";const w=JSON.parse('{"title":"Sensitive content handling","description":"","frontmatter":{},"headers":[],"relativePath":"security/sensitive-content.md","filePath":"security/sensitive-content.md"}'),c={name:"security/sensitive-content.md"};function h(g,e,u,p,f,m){const a=o("Badge");return s(),r("div",null,[e[0]||(e[0]=t("h1",{id:"sensitive-content-handling",tabindex:"-1"},[i("Sensitive content handling "),t("a",{class:"header-anchor",href:"#sensitive-content-handling","aria-label":'Permalink to "Sensitive content handling"'},"​")],-1)),d(a,{type:"built",text:"Built"}),e[1]||(e[1]=l(' Octryx AI examines what goes to a model for sensitive content and acts on it per content kind. A Workspace admin chooses the action for each kind; a fresh install starts with the defaults below.<p>The kinds: credentials, credential assignments, email addresses, internal IP addresses, IBANs and phone numbers.</p><p>There are two places where this happens, and they work differently:</p><ul><li><strong>The platform&#39;s own model calls</strong>: the chat, tasks, governed runs and tool results. All five actions apply here.</li><li><strong>The gateway of external coding agents</strong>: the requests of Claude Code and Codex, on the governed route and on a seat. A request is forwarded unchanged or refused; nothing is masked or rerouted there.</li></ul><h2 id="defaults" tabindex="-1">Defaults <a class="header-anchor" href="#defaults" aria-label="Permalink to &quot;Defaults&quot;">​</a></h2><p>These apply on a fresh install, and in every Workspace that changes nothing.</p><table tabindex="0"><thead><tr><th>Where</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Platform&#39;s own model calls</strong></td><td>Credentials and email addresses are masked, internal IP addresses are reported, IBANs and phone numbers are not acted on</td></tr><tr><td><strong>Gateway of external coding agents</strong></td><td>Credentials are refused, credential assignments are reported (the request goes on, the finding is recorded); nothing else is acted on</td></tr><tr><td><strong>Command safety</strong></td><td>A command with credentials or internal IP addresses is sent for review</td></tr></tbody></table><h2 id="the-five-actions" tabindex="-1">The five actions <a class="header-anchor" href="#the-five-actions" aria-label="Permalink to &quot;The five actions&quot;">​</a></h2><p>A Workspace admin chooses one per kind in <strong>Agents › Governance › Policy</strong>, card <strong>Sensitive content handling</strong>. On the platform&#39;s own model calls:</p><table tabindex="0"><thead><tr><th>Action</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Refuse</strong> (<code>refuse</code>)</td><td>The request is not sent. The caller gets <code>content_policy_denied</code>.</td></tr><tr><td><strong>Mask</strong> (<code>mask</code>)</td><td>Each value is replaced by a numbered placeholder before the model sees it.</td></tr><tr><td><strong>Reroute</strong> (<code>reroute</code>)</td><td>The request goes to the Workspace&#39;s governance alias.</td></tr><tr><td><strong>Mask and reroute</strong> (<code>mask_reroute</code>)</td><td>Masked, and sent to the governance alias.</td></tr><tr><td><strong>Report only</strong> (<code>report</code>)</td><td>The text goes to the model unchanged; the finding is recorded as an informational decision.</td></tr></tbody></table><p>An admin can also set a kind back to its shipped default. Before you save, the card shows what the chosen action does at every place; on the gateway it shows &quot;platform calls only&quot; wherever the choice does not act there.</p><h3 id="the-governance-alias" tabindex="-1">The governance alias <a class="header-anchor" href="#the-governance-alias" aria-label="Permalink to &quot;The governance alias&quot;">​</a></h3><p>Each Workspace has one <strong>governance alias</strong>: the single governed model alias (an alias of an active model gateway) that every rerouting kind is sent to. Kinds carry no alias of their own.</p><ul><li>A kind can be set to reroute only while the Workspace has a governance alias (<code>content_handling_alias_required</code>).</li><li>The alias cannot be cleared while a kind still reroutes (<code>content_handling_alias_in_use</code>, naming the kinds); it can only be replaced by another governed alias.</li></ul><h3 id="where-reroute-does-not-apply" tabindex="-1">Where reroute does not apply <a class="header-anchor" href="#where-reroute-does-not-apply" aria-label="Permalink to &quot;Where reroute does not apply&quot;">​</a></h3><ul><li><strong>A model&#39;s reply</strong> goes back to the user, not to another model. There reroute and mask and reroute mask instead, and the decision record says which action was requested and which was applied.</li><li><strong>A direct provider driver, and commands:</strong> reroute and mask and reroute are refused with <code>content_route_unavailable</code>.</li></ul><h2 id="on-the-gateway-of-external-coding-agents" tabindex="-1">On the gateway of external coding agents <a class="header-anchor" href="#on-the-gateway-of-external-coding-agents" aria-label="Permalink to &quot;On the gateway of external coding agents&quot;">​</a></h2><p>The gateway protects against <strong>accidental</strong> leakage by your own coding agent and against prompt injection arriving in tool results. It does not defend against a deliberately evasive client: Claude Code and Codex are your own programs and can reach any provider directly.</p><ul><li><strong>Forwarded unchanged or refused.</strong> The bytes sent are exactly the payload the gateway scanned.</li><li><strong>Only credentials and credential assignments act there.</strong> Credentials are refused by default, credential assignments reported by default; a Workspace can set <strong>Refuse</strong> or <strong>Report only</strong> for either. A credential assignment is a field whose name ends in a credential name (<code>password</code>, <code>db_password</code>, <code>access_token</code>, <code>client-secret</code>, …) with a literal value, also inside tool arguments, tool results and embedded JSON.</li><li><strong>Every other kind, and mask and the reroutes, apply to platform calls only.</strong> On the gateway such a setting leaves the kind at its default: a credential set to mask stays refused there.</li><li><strong>Prompt injection is checked only inside tool results</strong> (Claude Code&#39;s <code>tool_result</code> blocks, Codex&#39;s tool-call outputs). Found there, the request is refused (<code>content_policy_denied</code>). It is not checked in tool definitions, in your text, in the assistant&#39;s text or in the client&#39;s system prompt.</li><li><strong>The Workspace&#39;s custom content policies</strong> are asked too. A policy that blocks refuses the request; a policy that would mask or reroute also refuses it (<code>content_handling_gateway_refused</code>), because the gateway changes nothing. In shadow mode the request is sent and what the policy would have done is recorded.</li><li><strong>Bodies that cannot be checked are refused:</strong> invalid JSON (<code>request_body_invalid</code>), a body over 16 MiB (<code>request_body_too_large</code>), or a check not finished within 10 seconds (<code>content_scan_unfinished</code>). The next request is examined again.</li></ul><p>A refusal and a report notice name the decision record and say what to do next: remove the affected message or start a new conversation (Claude Code: <code>/rewind</code> or <code>/clear</code>; Codex: start a new session). A credential refusal names the kind of credential on the run&#39;s timeline.</p><h2 id="what-stays-fixed" tabindex="-1">What stays fixed <a class="header-anchor" href="#what-stays-fixed" aria-label="Permalink to &quot;What stays fixed&quot;">​</a></h2><p>No setting changes these:</p><ul><li>Text the detectors could not finish examining is withheld from a platform call; on the gateway the request is refused.</li><li>Content of an unknown shape in a platform call is refused (<code>content_unreadable</code>).</li><li>Prompt injection is refused: in every field a platform call sends to a model, and on the gateway in tool results.</li></ul><h2 id="who-can-change-it" tabindex="-1">Who can change it <a class="header-anchor" href="#who-can-change-it" aria-label="Permalink to &quot;Who can change it&quot;">​</a></h2><p>Workspace admins and owners, and platform admins. Members see the action in effect for each kind, and whether it is the default. Every change of an action or of the governance alias is written to the audit log as <code>content_handling.changed</code>; see <a href="/docs/admin/governance">Governance</a>.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><p>These are known in 0.0.1-alpha and planned for 0.0.2:</p><ul><li>The gateway&#39;s threat model is accidental leakage, not a deliberately evasive client (see above).</li><li>On the gateway, masking and rerouting do not happen: a request is forwarded unchanged or refused.</li><li>A few opaque fields are skipped by key name without checking their content: a thinking block&#39;s signature, encrypted reasoning or session state, and inline images and files (<code>data:</code> URLs, base64 media).</li><li>On the gateway, prompt injection is checked only inside tool results.</li><li>Which findings were already reported is kept in memory: after a restart, a finding is reported once more.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/security/redaction">Secret redaction</a>: secrets replaced with <code>[redacted]</code> before text is stored, shown or sent on.</li><li><a href="/docs/rules/policies">Policies and four-eyes</a>: policies, detectors and the <strong>Content security</strong> overview.</li><li><a href="/docs/security/data-classes">Data classes</a>: which models may see a Workspace&#39;s data at all.</li></ul>',30))])}const k=n(c,[["render",h]]);export{w as __pageData,k as default};
